type CartLine = OrderItem & { stock?: number };
const money = (value: number) => `₦${value.toLocaleString('en-NG')}`;
const dateLabel = (value: string) => new Date(value).toLocaleDateString('en-NG', { day: 'numeric', month: 'short', year: 'numeric' });
const imageFallback = (name: string) => `linear-gradient(135deg, hsl(278 50% 12%), hsl(43 40% 25%))`;

function useCart() {
  const [items, setItems] = useState<CartLine[]>(() => {
    try { return JSON.parse(localStorage.getItem('adodo-cart') || '[]'); } catch { return []; }
  });
  const update = (next: CartLine[]) => { setItems(next); localStorage.setItem('adodo-cart', JSON.stringify(next)); };
  const add = (product: Product) => {
    const existing = items.find((item) => item.productId === product.id);
    update(existing ? items.map((item) => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item) : [...items, {
      productId: product.id, name: product.name, quantity: 1, price: product.price, image: product.image, stock: product.stock,
    }]);
  };
  const remove = (id: number) => update(items.filter((item) => item.productId !== id));
  const change = (id: number, amount: number) => update(items.map((item) => item.productId === id ? { ...item, quantity: Math.max(1, item.quantity + amount) } : item));
  return { items, add, remove, change, clear: () => update([]), count: items.reduce((sum, item) => sum + item.quantity, 0), total: items.reduce((sum, item) => sum + item.price * item.quantity, 0) };
}

